public class Main {
    public static void main(String[] args) {
        int age = 10;
        int day = 6;

        // A chain, because these are ranges.
        String category;
        int price;
        if (age < 5) {
            category = "Infant";
            price = 0;
        } else if (age < 13) {
            category = "Child";
            price = 120;
        } else {
            category = "Adult";
            price = 250;
        }

        // A switch, because these are fixed values.
        String dayName = switch (day) {
            case 1 -> "Monday";
            case 2 -> "Tuesday";
            case 3 -> "Wednesday";
            case 4 -> "Thursday";
            case 5 -> "Friday";
            case 6 -> "Saturday";
            case 7 -> "Sunday";
            default -> "Unknown";
        };

        // A nested if: the surcharge is only for paying tickets.
        boolean weekend = day == 6 || day == 7;
        if (price > 0) {
            if (weekend) {
                price += 50;
            }
        }

        // A ternary, because it only chooses a word.
        String rate = weekend ? "weekend rate" : "weekday rate";

        System.out.println(dayName + ", " + rate);
        System.out.println(category + ": " + price);
    }
}

